(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["so"] = {"ui":{"skip":"U gudub nuxurka","back":"← Ku laabo AI-gile","lang.button":"Luuqad: {name}","lang.dialog":"Dooro luqad","lang.search":"Raadi luqadaha","lang.none":"Luqad waafaqsan ma jirto","lang.notYet":"{name} wali lama turjumin","theme.aria":"Beddel mawduuca: iftiin, mugdi ama madow","theme.toLight":"U beddel mawduuca iftiinka","theme.toDark":"U beddel mawduuca mugdiga","theme.toBlack":"U beddel mawduuca madow (madow dhab ah, ku fiican shaashadaha OLED)","words.underline":"Hoosta ka xarriiq erayadan bogga ku jira","words.underlineHelp":"Dul mar ama taabo eray dhibcaysan si aad u aragto macnihiisa.","index.title":"AI-gile: kooxdaada AI ee horumarinta, hal looxa","index.description":"AI-gile waa looxa kanban ee kooxaha barnaamijinta AI. Way shaqeeyaan inta aad hurdo; adiga waxaa kuu yimaada hal xirmo gaaban oo wax aad go'aamiso, tijaabiso oo aqbasho.","hero.logoAlt":"Astaanta looxa AI-gile","hero.h1.html":"Kooxdaada AI ee horumarinta, hal&nbsp;looxa.","hero.alpha":"🐣 Pre-alpha xiran","hero.alphaTitle":"Waa hore oo aan dhammaystirnayn: mahadsanid tijaabintaada!","hero.lede":"Way dhisaan inta aad hurdo. Waxaad toosaysaa hal xirmo gaaban: dhowr su'aalood, dhowr wax oo la tijaabiyo, hal ama laba dheeman oo guduudan-buluug ah. Guji, aqbal, oo ku laabo qaxwahaaga.","dl.windows":"Abka Windows","dl.browser":"Ku fur biraawsarka","dl.messenger":"📱 Messenger taleefankaaga","dl.soon":"Dhowaan","dl.notify":"🔔 I sheeg marka la furo","dl.notifySmall":"Alpha ama beta","hero.secondary":"Agile, laakiin kooxdu waligeed uma baahna qaxwada kulanka gaaban. (Kulamada gaagaabyada ah way sameeyaan si kastaba.)","pitch.h2":"AI-gile ereyo intaad rabto ku jira","pitch.lede":"Dooro dherer, hal eray ilaa 144. Dherer kasta waa sharaxaad u gaar ah, loo qoray cabbirkaas. Jiid sabuurka ama isticmaal fallaadhaha.","pitch.rangeLabel":"Dhererka ereyada","pitch.dice":"🎲 nooc kale","pitch.words.one":"{n} eray","pitch.words.other":"{n} eray","pitch.letters.one":"{n} xarfo","pitch.letters.other":"{n} xarfood","pitch.chars.one":"{n} xaraf","pitch.chars.other":"{n} xaraf","count.line.html.one":"{n} kaar ayaa hadda looxa ku jira","count.line.html.other":"{n} kaar ayaa hadda looxa ku jira","features.aria":"Wuxuu sameeyo","f.pile.h":"Hal xirmo adiga kuu ah","f.pile.html":"<b>Adiga</b> wuxuu ururiyaa wax kasta oo ku sugaya, mashruuc kasta: su'aalo, wax la tijaabiyo, hawlo uu qof kaliya samayn karo. Safkaaga ayaa kuu sheegaya waxa xiga iyo inta uu qaadanayo.","f.sleep.h":"Kooxo shaqeeya inta aad hurdo","f.sleep.p":"Mashruuc kastaa wuxuu leeyahay hoggaamiye iyo koox wakiilo AI ah. Kaarka ka dhiib faallo, kooxdu way toostaa, shaqada way qabataa, oo waxay kuu soo celisaa tallaabooyin uu qof daallan raaci karo.","f.tester.h":"Tijaabiyaha AI ayaa marka hore hubiya","f.tester.p":"Intaan wax adiga kuu imaan, tijaabiyuhu wuxuu raacaa tallaabooyinka nuqul ka mid ah abka wuxuuna muujiyaa waxa uu arkay, isagoo leh sawir shaashad. Dhex mar kuwa gudbay oo ku aqbal hal gujin.","f.proof.h":"Caddayn, ma ahan ballanqaadyo","f.proof.p":"Gacan-ka-gacan kasta wuxuu muujiyaa waxa isbeddelay: faylasha, farqiga, sawirada shaashadda. Uma baahnid inaad fureyso abka kasta si aad u aragto in la dhammeeyay.","f.chat.h":"La sheekayso hoggaamiyayaashaada","f.chat.p":"Tiir u eg Discord: hal astaan mashruuc kasta, dheeman guduudan-buluug ah waxa adiga ku baahan. Hoggaamiye u dir fikrad; wuxuu u beddelaa kaararka iyo qorshe, iyo badhanka ✅ Bilow.","f.tidy.h":"Is nadiifiya","f.tidy.p":"Kaararka isku xiga way is-dhex galaan, cinwaannada qalafsan waa la saxaa, hubinta tokenka ayaa koodhka ilaaliya mid khafiif ah. Wax yar oo la beddelo, wax yar oo la fekero.","f.private.h":"Adigaa leh, kombiyuutarkaaga","f.private.li1":"Looxu wuxuu ku shaqeeyaa mashiinkaaga, wuxuuna ka jawaabaa adiga oo keliya.","f.private.li2":"Fariimaha gaarka ah ee dadka dhexdooda waa la sir-qarsoodiyey dhammaadka ilaa dhammaadka.","f.private.li3":"Akoon ma jiro, raadraac ma jiro, cookies ma jiraan.","f.lang.h":"Luqaddaada","f.lang.p":"In ka badan 120 luqadood, Holandays, Welsh iyo Jabaaniis ilaa budhcad-badeed, Yoda iyo Klingon, oo leh beddelid degdeg ah oo Ingiriisi ah ee ereyada xirfadda.","f.service.h":"Fikrad ilaa adeeg dhab ah","f.service.p":"Ma ku dhistay AI wax dadku hadda isticmaalaan? U calaamadee adeeg, sabuuraduna waxay kaa caawinaysaa inaad si fiican u maamusho: hubinta shaqeynta, bog xaaladeed oo dadweyne, shilal leh dib-u-eegis qoran, isbeddello u baahan Go, kaydad maalin kasta la hubiyo. Caawimadu waxay ku bartaa tallaabo kasta intaad socoto.","msgr.h2":"AI-gile Messenger: kooxdaadu jeebkaaga","msgr.p1":"La hadal kooxdaada AI adigoon furin boardka. La sheekayso hoggaamiyeyaasha mashruucaaga iyo saaxiibbadaa, oo arag tallaabooyinka tijaabada ee kaar oo ka jawaab, dhammaan taleefankaaga.","msgr.p2":"Si aad isugu xirto, iskaan garee QR code ku yaal boardkaaga. Markii ugu horreysay? Sheeko demo ah oo saaxiibtinimo leh ayaa ku tusaysa.","msgr.when":"Marka hore Android, kadib nooc web ah oo loogu talagalay taleefannada iyo iPhone.","msgr.who":"Hoggaamiyaha mashruucaaga","msgr.b1":"Hagaajinta habka mugdiga diyaar weeye. Ma rabtaa tallaabooyinka tijaabada?","msgr.b2":"Haa, fadlan!","msgr.b3":"1. Fur Settings. 2. Dooro Dark. Si sax ah ma u muuqataa?","tl.aria":"Jadwalka laga bilaabo wada hadalkii ugu horreeyay ilaa qorshaha","tl.h2":"Sheekadii ugu horreysay ilaa waxa xiga","tl.lede":"Taariikho iyo waqtiyo dhab ah, aagga waqtigaaga. Maanta ka dib waa qorshe, taariikho lama ballanqaadin.","tl.today":"Maanta","tl.planned":"la qorsheeyay","tl.cards.one":"{n} kaar","tl.cards.other":"{n} kaar","join.h2":"Ku soo biir","join.lede":"AI-gile waxaa dhisaya nin gadh leh oo qariib ah, qaba AuDHD, oo dhowr jeer la dagaalamay caafimaadka maskaxda, iyo wakiilo badan oo samir badan. Hadda waa gaar, alpha xiran oo asxaab ah. Ma rabtaa inaad tijaabiso marka la furo?","join.btn":"Muuji xiisaha","join.small":"Iimayl ayaan kuu qori doonaa, wax kale ma jiro","footer.tag":"AI-gile. Raadraac la'aan, cookies la'aan, qaxwo kulan la'aan.","footer.licence":"Shahaadada ganacsiga","footer.status":"Xaaladda","footer.privacy":"Waxa aan haynno","footer.thanks":"Wicitaanada waxaa suurtagaliyay ChilledChat","form.sending":"Waa la dirayaa…","form.failed":"Ma shaqayn: mar dambe isku day.","form.offline":"AI-gile lama gaari karin: mar dambe isku day.","form.keep":"Waxaan u isticmaalnaa oo keliya inaan kuugu jawaabno, kadibna waan tirtirnaa. Raadraac la'aan, cookies la'aan.","form.keepLink":"Waxa aan haynno","interest.title":"AI-gile: i sheeg marka alpha la furo","interest.description":"Iimaylkaaga reeb si aad u ogaato marka alpha ama beta xiran ee AI-gile la furo.","interest.h1":"🔔 I sheeg marka la furo","interest.lede":"AI-gile waa pre-alpha xiran. Iimaylkaaga reeb, mar keliya ayaan kuu qori doonnaa marka meel adiga kuu jirto.","interest.email":"Iimaylkaaga","interest.which":"Tijaabo kee?","interest.alpha":"Alpha xiran: hore, qallafsan, isbeddello badan","interest.beta":"Beta: xasiloon, dambe","interest.both":"Mid kasta, kii hore yimaada","interest.submit":"Liiska igu dar","interest.thanks":"Mahadsanid! Liiska waad ku jirtaa.","licence.title":"AI-gile: shahaadada ganacsiga","licence.description":"Ma ku isticmaashaa AI-gile ganacsigaaga? Codso shahaado ganacsi oo bilaash ah.","licence.h1":"📜 Shahaadada ganacsiga","licence.lede":"Ma ku isticmaashaa AI-gile shaqada? Noo sheeg yaad tahay iyo waxaad qabato. Haddii wax wanaagsan sameeyo, shahaadadu waa bilaash.","licence.company":"Shirkadda","licence.website":"Boggaga","licence.what":"Waxaad qabato","licence.how":"Sida ay adduunka ugu caawiso","licence.email":"Iimaylka","licence.submit":"Codso","licence.thanks":"Mahadsanid! Iimayl ayaan kaaga jawaabi doonnaa.","status.title":"Xaaladda AI-gile","status.h1":"Xaaladda AI-gile","status.quiet":"Wax walba way degan yihiin","status.intro":"AI-gile ma shaqaynayaa hadda? Boggan wuxuu 5-tii daqiiqoba mar hubiyaa website-ka, wadaagista looxyada, wicitaannada iyo soo dejinta.","status.up":"Wuu shaqaynayaa (wuxuu ku jawaabay {ms} ms)","status.slow":"Kama jawaabin hubintii u dambaysay, mar kale ayaan isku dayayaa","status.down":"Wuu xiran yahay: kama jawaabin labadii hubin ee u dambeeyay","status.svc.web":"Website-ka","status.svc.web.offers":"Boggan: waxa uu AI-gile yahay, iyo foomka xiisaha","status.svc.boards":"Wadaagista looxyada","status.svc.boards.offers":"Looxyo dadweyne, fariimo saaxiibbada dhexdooda ah iyo casuumado","status.svc.calls":"Wicitaannada","status.svc.calls.offers":"Cod, muuqaal iyo wadaagista shaashadda gudaha AI-gile","status.svc.download":"Soo dejinta","status.svc.download.offers":"Rakibaha Windows iyo xiriirinnada casuumadda","status.checking":"Waa la hubinayaa…","status.offline":"Adeegga xaaladda hadda lama gaari karo (mar kale ayaan isku dayayaa)","status.updated":"la cusboonaysiiyay {ago}","status.justNow":"hadda dhawaan","status.min":"{n} daqiiqo ka hor","status.hours":"{n} saac ka hor","status.days":"{n} maalmood ka hor","privacy.title":"AI-gile: waxa aan haynno","privacy.h1":"Waxa aan haynno","privacy.lede":"Si kooban: kaliya waxaad noo soo dirto, mana aha muddo dheer.","privacy.only":"Kaliya waxaad noo soo dirto: waxaad ku qorto foom, sida iimaylkaaga. Wax kale oo adiga kugu saabsan ma jiraan.","privacy.sealed":"Waa la shaabadeeyaa si server-kayagu aanu u akhrin karin: biraawsarkaaga gudahiisa ka hor intaanu bixin (biraawsar duug ah, isla marka uu yimaado). Kaliya looxayaga ayaa furi kara.","privacy.server":"Server-ka waa laga tirtiraa isla marka uu gaaro looxayaga. Wax kasta oo halkaas ku haray 30 maalmood kadib si kastaba waa la tirtiraa.","privacy.board":"Waxaan ku haynaa looxayaga oo keliya ilaa aan kaaga jawaabno, kadibna halkaasna waan ka tirtirnaa.","privacy.none":"Raadraac la'aan, cookies la'aan, falanqayn la'aan.","privacy.local":"Luqaddaada iyo doorashadaada iftiinka ama mugdiga waxay ku jiraan biraawsarkaaga. Weligood nalooma soo diro.","privacy.ask":"Ma rabtaa in hore loo tirtiro? Ka jawaab iimaylkayaga oo noo sheeg.","live.h2":"Daawo markii la dhisayo, tooska","live.caption":"Kaarkasta waa qarsoon yahay: waxaad aragtaa qaabka shaqada, ma aha erayada.","live.watching.one":"tooska: {n} ayaa daawanaya","live.watching.other":"tooska: {n} ayaa daawanaya","live.last.now":"Kaarkii ugu dambeeyay waa la dhaqaajiyay hadda","live.last.min.one":"Kaarkii ugu dambeeyay waa la dhaqaajiyay {n} daqiiqo ka hor","live.last.min.other":"Kaarkii ugu dambeeyay waa la dhaqaajiyay {n} daqiiqo ka hor","live.last.hour.one":"Kaarkii ugu dambeeyay waa la dhaqaajiyay {n} saac ka hor","live.last.hour.other":"Kaarkii ugu dambeeyay waa la dhaqaajiyay {n} saacadood ka hor","live.last.day.one":"Kaarkii ugu dambeeyay waa la dhaqaajiyay {n} maalin ka hor","live.last.day.other":"Kaarkii ugu dambeeyay waa la dhaqaajiyay {n} maalmood ka hor","live.offline":"Looxa tooska ah wuxuu qaadanayaa nasasho yar. Dhawaan dib u soo eeg.","live.cols":"Backlog|Waxa la sameeyo|Socda|Kooxdu way eegaysaa|Adiga oo test samaynaya|Kooxda|La dhammeeyay"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotyo.","Wakiilnimo."]},{"n":2,"texts":["Kanban robot.","Wakiilo nidaamsan.","Fikrado dhisan."]},{"n":3,"texts":["Kanban u ah robotyada.","Fikrad, dhis, aqbal.","Kanban wakiilo bilaash."]},{"n":5,"texts":["Looxa kanban oo wakiilo maamulaan.","Adigu qor kaararka. Wakiilladu dhis.","Bilaash, gudaha, tijaabo, qosol yar."]},{"n":8,"texts":["Looxa kanban oo bilaash ah halka wakiilo AI shaqeeyaan.","Qor fikrad. Wakiilladu way dhisaan. Adigu aqbal.","Agile hal qof iyo robotyo badan oo samir badan."]},{"n":13,"texts":["Looxa kanban ee kombiyuutarkaaga ku jira halka wakiilo AI ay kaararka qaataan oo ay ku shaqeeyaan.","Qor fikrad. Koox wakiilo ah ayaa dhisa. Tijaabiye ayaa hubiya. Adigu waxaad dhahdaa haa.","Bilaash, akoon la'aan, raadraac la'aan: looxa, robotyo yar, iyo adiga oo xukumaya."]},{"n":21,"texts":["AI-gile waa looxa kanban oo lagu la shaqeeyo wakiilo AI ah oo barnaamijiya. Iyagu kaararka way qaataan; adiguna waad tijaabisaa oo aqbashaa.","Mashruuc kastaa wuxuu helaa hoggaamiye iyo koox wakiilo AI ah. Kaar kasta faallo ka qor, kooxduna way shaqo bilaabaysaa.","Looxa hawlaha shaqsiyeed oo bilaash ah oo kombiyuutarkaaga ku shaqeeya. Shaqaaluhu waa robotyo. Kan dhihi kara haa waa adiga."]},{"n":34,"texts":["Fikradaha looxa ayaad saartaa. Koox wakiilo AI ah ayaa u beddesha qaybo shaqeeya, way tijaabisaa, waxayna kuu soo celisaa tallaabooyin lagu tijaabiyo. Wax lama yiraahdo waa dhammaaday ilaa aad dhahdo.","AI-gile waa looxa kanban oo guri lagu sameeyay, kaas oo Rich ku dhisay caawimo badan oo ka timid wakiilada uu hadda xukumo. Waa bilaash, kombiyuutarkaaga ayuu ku shaqeeyaa, waxaana lala wadaagaa asxaabta, lama iibiyo.","Ka fikir looxa kanban oo caadi ah, oo leh tiirar laga bilaabo Backlog ilaa La dhammeeyay, marka laga reebo in kaararka qaataan wakiilo AI. Waxay sheegaan horumarka, waxay weydiiyaan marka ay hakadaan, had iyo jeer waxayna sugaan oggolaanshahaaga."]},{"n":55,"texts":["AI-gile waa looxa kanban oo kooxdu ka kooban tahay wakiilo AI. Mashruuc kastaa wuxuu leeyahay hoggaamiye qorsheeya shaqada iyo caawiyayaal dhisa. Marka sifo diyaar tahay, tijaabiye AI ah ayaa tijaabiya oo sawir shaashad qaata, ka dibna waxay ku dhacdaa xirmadaada. Aqbal, ama faallo qor, waana dib u sameeyaan.","Wuxuu ku bilaabmay hab qof keliya uu ku raaco fadhiyo badan oo barnaamijin AI ah isku mar, wuuna kobcay oo noqday looxa dhab ah. Wuxuu ku shaqeeyaa mashiinkaaga, akoon uma baahna, raadraac ma laha. Waa bilaash asxaabta iyo kuwa xiisaynaya. Sidoo kale ma dhammaystirna, sidaa darteed filo geesyo qallafsan iyo layaab mararka qaarkood.","Halkan waa nooca daacadda ah. Adigu weli waa inaad fikrado yeelataa, weliba waa inaad hubisaa natiijooyinka. AI-gile wuxuu qabtaa wax kasta oo u dhexeeya: kaararka ayuu u dhigaa nidaam, wuxuu kiciyaa wakiilka saxda ah marka aad faallo qorto, wuxuu tusaa si sax ah waxa isbeddelay, wuxuuna dhammaantood ku soo ururiyaa hal xirmo gaaban adiga kuu ah."]},{"n":89,"texts":["AI-gile waa looxa kanban oo bilaash ah oo aad ku wadato kombiyuutarkaaga. Halkii dad, mashruuc kastaa wuxuu leeyahay koox wakiilo AI ah: hoggaamiye u beddela fikradahaaga kaararka iyo qorshe, iyo caawiyayaal kaararka qaata marka la horumariyo. Marka wax la dhiso, tijaabiye AI ah ayaa raaca tallaabooyinka tijaabada oo kuu muujiya waxa uu arkay. Kadib wuxuu ku sugaa hal xirmo la yiraahdo Adiga. Waad aqbashaa, ama faallo ayaad qortaa kooxduna mar kale ayay isku dayaan. Wax kuma gaaraan La dhammeeyay adiga la'aantaa.","Dhowr wax oo laga yaabo inaadan filayn. Ilaaliyaha habeenka ayaa buuxiya tiirka Waxa la sameeyo inta aad hurdo, isagoo dooranaya kaararka aan jawaab kaa rabin. Tiriyaha tokenka ayaa muujiya intii wakiilladu isticmaaleen maanta iyo toddobaadkan, Habka Tokenka La'aan ayaana u sheegaya inay joojiyaan isticmaalka. Waad la fariisan kartaa asxaabta, fariimaha gaarka ahna waa la sir-qarsoodiyey dhammaadka ilaa dhammaadka. Looxu wuxuu ku hadlaa ilaa 120 luqadood, oo ay ku jiraan Holandays, Flemish, budhcad-badeed iyo Klingon. Midkoodna sentimo ma ku kacayo, cidna isku dayin inay kuu iibiso.","AI-gile waa mashruuc yar oo shakhsi ah, ma aha shirkad. Rich wuxuu rabay inuu ilaaliyo dhowr mashruuc oo barnaamijin AI ah isagoo aan furin abka kasta si uu u hubiyo, sidaa darteed isaga iyo wakiilladu waxay dhiseen looxa, kadibna looxa ayay ku dhiseen inta kale ee naftiisa. Waa pre-alpha xiran, taasoo la macno ah inuu shaqeeyo, inta badan, koox yar oo asxaab ah. Bog qiimo ma leh, wargeys ma leh, qorshe kobac ma leh. Haddii ay kuu ekaato mid faa'iido leh, waad codsan kartaa inaad tijaabiso marka wax yar ka badan la furo."]},{"n":144,"texts":["AI-gile waa looxa kanban oo hal qof iyo wakiilo AI badan u ah. Wuxuu ku shaqeeyaa kombiyuutarkaaga wuxuuna yahay bilaash dhan. Waxaad ku darsataa mashruucyo, mid kastana wuxuu helaa hoggaamiye iyo koox yar. Waad la sheekaysataa hoggaamiyaha, in yar sida Discord, waxaadna sifaysaa fikrad; hoggaamiyuhu wuxuu u beddelaa kaararka iyo qorshe, kadibna wuu sugaa inta aad gujinayso Bilow. Kooxdu waxay kaararka u gudubtaa sida mudnaanta u ahaato, iyadoo isticmaalaysa xariiq amar fudud oo loo sameeyay moodooyinka luqadda. Intaan wax kuu soo noqon, tijaabiye AI ah ayaa raaca tallaabooyinka nuqul ka mid ah abka oo ku lifaaqa sawir shaashad. Shaqada dhammaatay waxay ku dhacdaa xirmadaada iyada oo leh faylasha la beddelay iyo farqiga. Waad aqbashaa, ama faallo ayaad ka tagtaa kooxduna way toostaa oo mar kale isku daydaa. Kaar u gudbin La dhammeeyay waxaad samayn kartaa adiga oo keliya.","Maalin AI-gile la qabo, qiyaas ahaan. Fiidkii waxaad ka tagtaa dhowr faallo: badhankan meel qaldan buu yahay, liiskaas waa in la kala saaro, ma yeelan karnaa habka mugdiga. Waad seexataa. Wakiilladu faallooyinka way akhriyaan, isbeddellada way samaystaan, way tijaabiyaan oo way kuu soo celiyaan. Haddii Waxa la sameeyo engegto, ilaaliyaha habeenka ayaa ka buuxiya backlog-ga kaararka aan jawaab kaa rabin. Subaxdii waxaa jirta hal xirmo gaaban: dhowr su'aalood iyo dhowr wax la tijaabiyo, mid kastana wuxuu leeyahay tallaabooyin uu qof hurdo ku jiro raaci karo iyo sawir muujinaya inuu shaqeeyo. Waad dhex marisaa, waxa wanaagsan aqbashaa, inta kalena celisaa. Tiriyaha tokenka ayaa muujiya waxa dhammaantood isticmaaleen, Habka Tokenka La'aan-na wuxuu u diyaar yahay toddobaadyada dhaqaalaha yar. Kadib waxaad cunta quraac, taas oo wakiilladu weli kaa caawin kari waayeen.","Marka hore, waxa AI-gile ahayn maaha. Ma aha startup, lama iibiyo, cidna ma ururiso xogtaada. Waa looxa bilaash ah oo kombiyuutarkaaga ku shaqeeya, akoon la'aan, raadraac la'aan iyo cookies la'aan. Waxa uu yahay: hal meel nadiif ah oo aad ku aragto mashruucyada barnaamijinta AI dhammaan isku mar, iyadoo koox wakiilo ah ay samaynayaan kaararka adiguna aad go'aamineyso. Wuxuu isku dhex yeelaa kaararka isku xiga, wuxuu saxaa cinwaannada qalafsan, wuxuuna fiiriyaa in koodhku khafiif ahaado. Wuxuu ku hadlaa ilaa 120 luqadood, laga bilaabo Holandays iyo Flemish ilaa budhcad-badeed iyo Klingon. Asxaabtu waa isu qori karaan gaar ahaan oo sir-qarsoodi ah. Waxaa dhisay Rich iyo tiro badan oo wakiilo samir badan ah, inta badan isagoo isticmaalaya naftiisa. Waa pre-alpha xiran, sidaa darteed meelaha qaarkood waa qallafsan yahay. Haddii ay kuu ekaato wax xiiso leh, si wanaagsan weydiiso, laga yaabee inaad hore u gasho."]}],"quips":{"1":"Hal eray. Dhiirrasho. Laga yaabee xad-dhaaf.","3":"Seddex eray. Hadda ka daacad badan bogagga badeecadaha intooda badan.","8":"Siddeed eray. Wali way ka gaaban yihiin kulan gaaban.","21":"Dhererradu waa story points, dariiqa. Hubaal ayay yihiin.","55":"Shan iyo konton eray. Laba kaar ayaa la dhammeeyay intaad akhrinaysay.","144":"Tani waa tan dheer. 233 ma jirto. Wakiilladii way seexdeen."}},"timeline":{"first-idea.name":"Fikraddii ugu horreysay","first-idea.line":"Wada hadalkii ugu horreeyay, intaan koodh jirin.","first-board.name":"Looxii ugu horreeyay","first-board.line":"Loox raacaya dhismihiisa: kaararka, tiirarka, jiid oo dhig, mashruucyada.","team-roles.name":"Koox iyo doorar","team-roles.line":"Astaamaha wakiilada, qaabdhismeedyada kooxaha, meelaha iyo yaa maxay qabanaya.","install.name":"Rakibid iyo daabacaado","install.line":"Zip uu saaxiib rakibi karo, is-cusboonaysiin, kanaalo iyo dib u noqosho.","usage-saver.name":"Badbaadiyaha isticmaalka","usage-saver.line":"Cabbir waxa socodku ku kacaan, koodhka khafiif ka dhig, xadkaaga badbaadi.","friends.name":"Asxaab iyo wadaagid","friends.line":"Fariimo gaar ah, gudbiye qarsoon, casuumaado, doorar iyo mashruucyo la wadaago.","languages.name":"Luqadaha","languages.line":"Qoraal shaashad kasta faylka luqadda, Holandays iyo Flemish marka hore.","ai-tester.name":"Tijaabiyaha AI","ai-tester.line":"Tijaabiye ayaa marka hore hubiya gacan-ka-gacan kasta oo muujiya waxa uu arkay.","website.name":"Mareegta","website.line":"aigile.lol, hordhaca iyo jadwalkan.","streaming.name":"Sheeko iyo tooska","streaming.line":"Discord, Twitch, OBS, habka tooska, GIF-yo iyo emoji.","no-ai.name":"Nooca aan AI lahayn","no-ai.line":"Loox dadka aan AI la'aan koodhka qorin, iyo looxyo dadweyne.","night-watch.name":"Ilaaliyaha habeenka","night-watch.line":"Ilaaliye iyo Scrum Master ayaa kooxaha shaqada ku haya inta aad hurdo.","p-more.name":"Wax kale oo dhan","p-more.line":"Fikrado yar oo wali sugaya inay noqdaan kuwa xiga.","p-android.name":"Taleefan iyo Android","p-android.line":"Looxaaga ka gaar taleefanka, kadibna abka Android ee asalka ah.","p-release.name":"Alpha iyo wixii ka dambeeya","p-release.line":"Alpha xiran, bogga tooska ah, kadibna beta.","p-languages.name":"Luqado dheeraad ah","p-languages.line":"In ka badan boqol luqadood iyo hab quusid ah oo loogu talagalay barteyaasha.","p-engines.name":"Mishiinno AI dheeraad ah","p-engines.line":"Dooro Claude, Codex ama Gemini wakiil kasta.","p-pro.name":"Hab-dhaqan xirfadeed","p-pro.line":"Calaamado khatar, albaabada isku-darka, kaararka dhacdooyinka iyo ilaalin.","p-self.name":"Ku daryeelidda adiga","p-self.line":"Habka daalka, xusuusinta is-daryeelka iyo 4:20.","p-servers.name":"Serfarro iyo ballaarin","p-servers.line":"Dejinta serfarka guud, doorar iyo qorsheynta kobaca.","p-livestream.name":"Dheeraadka tooska","p-livestream.line":"Sheekada Twitch, emoji gaar ah iyo muuqaal tooska ah oo dadweyne."},"words":{"button":"📖 Ereyada xirfadda","h":"📖 Ereyada la sharraxay","intro":"Ereyada aad kula kulanto AI-gile, si fudud loo sharraxay: dhisidda, si ammaan ah wax uga beddelidda, ka dhigidda inay u shaqeyso dadka isticmaala, iyo ka shaqeynta koox ahaan oo AI la jirto.","search":"Raadi eray…","none":"Eray ku habboon ma jiro.","close":"Xir","count":{"one":"{count} eray","other":"{count} eray"},"groups":[{"id":"build","name":"🛠️ Dhisidda"},{"id":"change","name":"🔀 Beddelid ammaan ah"},{"id":"run","name":"🛎️ Maamulidda adeeg"},{"id":"team","name":"🤝 Ka shaqeynta koox ahaan (iyo AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Folderka mashruuca ee koodhka iyo taariikhdiisa oo dhan ee commits-ka, inta badan sidoo kale lagu hayo GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Xariiq shaqo oo gaar ah koodhka ku jira, si isbeddello loo sameeyo iyada oo aan la taaban nooca ugu weyn.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Sawir la keydiyay oo koodhka ah, oo leh qoraal gaaban oo ku saabsan waxa isbeddelay. Had iyo jeer waad ku laaban kartaa mid.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"U dirista sawirrada la keydiyay (commits) kombuyuutarkan una gaarsiinta GitHub, si loo kaydiyo loona wadaago."},{"id":"merge","g":"build","word":"Merge","text":"Dib ugu biirinta isbeddelada branch-ka nooca ugu weyn."},{"id":"pr","g":"build","word":"Pull request","text":"Codsiga in isbeddelada branch la hubiyo oo lagu daro nooca ugu weyn.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Nadiifinta koodhka iyada oo aan la beddelin waxa uu sameeyo: faylal yar yar, magacyo cad, soo noqnoqod yar."},{"id":"bug","g":"build","word":"Bug","text":"Wax aan sidii loogu talagalay u shaqaynayn.","also":["bugs"]},{"id":"test","g":"build","word":"Test","text":"Isku dayga shaqo dhammaatay si loo hubiyo inay sameyso waxa la weydiistay, ka hor intaadan aqbalin.","also":["tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Soo gaabinta quality assurance, xaqiijinta tayada: hubinta otomaatigga ah ee socota ka hor inta aan wax toos u bixin. Marka QA uu casaan yahay, wax baa fashilmay, mana bixi karo ilaa la hagaajiyo.","also":["hubinta tayada","xaqiijinta tayada"]},{"id":"deploy","g":"change","word":"Deploy","text":"Dejinta nooc cusub toos ah, tusaale server dadku ku isticmaalaan."},{"id":"release","g":"change","word":"Sii deyn","text":"Xirmo magac leh oo shaqo dhammaatay ah oo wada toos u baxda, oo leh qoraallo gaaban oo ku saabsan waxa isbeddelay. 🚀 Sii deynta waxay qoraallada ka qortaa kaarrada la dhammeeyay.","also":["sii deynta","release"]},{"id":"rollback","g":"change","word":"Dib u celin","text":"Ku noqoshada nooca ugu dambeeyay ee shaqeynayay marka mid cusub dhibaato keeno. AI-gile waxay ka samaysaa liis hubin ah oo leh tallaabooyinka laga noqonayo ee ku qoran isbeddel kasta.","also":["rollback","dib u celi","dib loo celiyay"]},{"id":"live","g":"change","word":"Toos","text":"Nooca dhabta ah ee dadku isticmaalaan, oo ka duwan nuqul wax lagu tijaabiyo. Horumarinta waxay sidoo kale u yaqaanaan production.","also":["live","production","wax-soo-saar"],"noTip":1},{"id":"change","g":"change","word":"Isbeddel","text":"Isbeddel la qorsheeyay oo lagu sameynayo wax dadku ku tiirsan yihiin, oo marka hore la qoray: maxay, sababta, khatarta, goorta iyo sida looga noqon karo. Ku bilow 🔀 Soo bandhig isbeddel.","also":["isbeddello","codsi isbeddel","codsiyo isbeddel"],"noTip":1},{"id":"risk","g":"change","word":"Khatar","text":"Wax khaldami kara, oo lagu qiimeeyay inta ay u badan tahay iyo inta ay xumaan lahayd. ⚠️ Khataro waxay ku hayaan hal liis, dhibcaha ugu sarreeya marka hore, mid kasta oo leh taariikh dib loogu eego.","also":["khataro","diiwaanka khatarta"]},{"id":"chgwin","g":"change","word":"Daaqad isbeddel","text":"Waqtiyada isbeddelladu toos u bixi karaan, sida fiid Talaado ah oo deggan. Daaqadda dibaddeeda kaar isbeddel lama dhammeyn karo, haddii aanay ahayn xaalad degdeg ah.","also":["daaqadaha isbeddelka","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Cod degdeg ah oo la bixiyo kahor inta isbeddel uusan toos u bixin: qof kasta oo ay tahay inuu oggolaado wuxuu yiraahdaa Go ama No go. Wuxuu socdaa oo keliya marka ay isku raacaan.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Oggolaansho","text":"Sugidda haa kahor inta shaqadu aanay bilaabmin. Kaar saaxiib soo gudbiyay, ama isbeddel, wuxuu ku sugayaa ✅ Oggolaanshaha ilaa aad oggolaato ama diido.","also":["oggolaanshaha","oggolow"]},{"id":"quiettime","g":"change","word":"Waqti aamusnaan","text":"Muddo, sida baahin toos ah, bandhig ama habeenka, oo aan waxba toos u bixin. Kooxuhu way sii shaqeeyaan oo tijaabiyaan, laakiin toos u bixiddu way sugtaa ilaa ay dhammaato. Meelo kale waxaa loo yaqaan change freeze.","also":["waqtiyada aamusnaanta","joojinta isbeddelka","change freeze"]},{"id":"service","g":"run","word":"Adeeg","text":"Wax aad dhistay oo dadku ku tiirsan yihiin, sida website ama app, oo la daryeelo si uu u sii shaqeeyo. Calaamadee “Mashruucan waa adeeg” oo sheeg waxa uu bixiyo, cidda isticmaasha iyo cidda xilka haysa.","also":["adeegyo","service"]},{"id":"uptime","g":"run","word":"Hubinta shaqeynta","text":"Hubin otomaatig ah, dhowr daqiiqo kasta, in adeeggaagu weli jawaabayo. Haddii ay dhowr jeer oo xiriir ah fashilanto, AI-gile waxay iskeed u furtaa kaar shil.","also":["uptime","hubinta uptime"]},{"id":"statuspage","g":"run","word":"Bogga xaaladda","text":"Bog dadweyne oo muujinaya in adeeg shaqeynayo iyo in kale (cagaar, oranji ama casaan) oo leh warkii ugu dambeeyay, si dadka isticmaala ay iska eegaan halkii ay weydiin lahaayeen.","also":["bogagga xaaladda","status page"]},{"id":"incident","g":"run","word":"Shil","text":"Wax hadda u jaban dadka isticmaala, sida website-ka oo dhacay. Kaar 🔥 shil ah wuxuu ka horreeyaa safka: in mar kale la shaqeysiiyo ayaa ugu horreysa.","also":["shilal","incident","dhacdo"]},{"id":"major","g":"run","word":"Shil weyn","text":"Shil weyn: dad badan ayaa saameeyay, ama lacag ama xog ayaa khatar ku jira. Hal badhan ayaa koox kasta ku dhejiya (koox wada shaqeysa), toosiya cidda xilka haysa, oo codsada war xaaladeed 30 daqiiqo kasta.","also":["shilal waaweyn","major incident","dhacdo weyn"]},{"id":"oncall","g":"run","word":"Xilka qaadid","text":"Inaad noqoto qofka jawaaba marka wax jabaan, xitaa habeenkii. Adeeg kasta wuxuu leeyahay xubin koox oo xilka haysa oo marka hore la toosiyo shilalkiisa.","also":["xilka haya","on call","on-call"]},{"id":"replyby","g":"run","word":"Waqtiga jawaabta","text":"Inta kaar sugi karo jawaabta koowaad, tusaale ahaan saacad shil ahaan. Kadib wuxuu helaa saacad casaan ah, si aan waxba si aamusnaan ah loo illaawin. Waxaa kale oo loo yaqaan bartilmaameedka jawaabta.","also":["waqtiyada jawaabta","bartilmaameedka jawaabta"]},{"id":"postmortem","g":"run","word":"Dib-u-eegis shil","text":"Dib u eegis gaaban kadib shil: waxa dhacay, waxa caawiyay iyo waxa la beddelayo, iyadoo aan qofna la eedeynin. Shil lama xiri karo la'aanteed. Inta badan waxaa loo yaqaan post-mortem.","also":["post-mortem","postmortem","dib-u-eegista shilka"]},{"id":"problem","g":"run","word":"Dhibaato","text":"Sababta qarsoon ee ka dambeysa hal shil ama ka badan. Kaar 🧩 dhibaato ah wuxuu isku keenaa shilalka soo noqnoqda, si sababta loo helo oo weligeed loo hagaajiyo.","also":["dhibaatooyin","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Sababta aasaasiga ah","text":"Sababta dhabta ah ee wax u jabeen, ma aha oo keliya waxa aad aragtay inay khaldameen. Hagaaji sababta aasaasiga ah, shilkuna wuu joojiyaa soo noqoshada.","also":["sababaha aasaasiga ah","root cause"]},{"id":"workaround","g":"run","word":"Xal ku meel gaar ah","text":"Hab lagu sii shaqeysiiyo waxyaabaha ilaa hagaajinta dhabta ahi diyaar noqoto, sida dib u kicinta wax marka uu xayirmo. Waxaa lagu qoraa kaarka dhibaatada si aan qofna u baahan inuu mar kale ogaado.","also":["xalal ku meel gaar ah","workaround"]},{"id":"knownerror","g":"run","word":"Khalad la yaqaan","text":"Dhibaato sababteeda la fahmay oo leh xal ku meel gaar ah, laakiin aan weli la hagaajin. 🧩 Khaladaadka la yaqaan ayaa liis gareeya, si qof walba u isticmaalo xalka ku meel gaarka ah halkii uu mar kale qodi lahaa.","also":["khaladaadka la yaqaan","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Tilmaamo tallaabo-tallaabo ah oo lagu hagaajiyo nooc dhibaato la yaqaan, si mar kasta isku si oo degdeg ah loo sameeyo. Kadib shil weyn kooxdu waxay kuu soo jeedin kartaa mid aad oggolaato.","also":["runbooks","tilmaamaha shaqada"]},{"id":"backup","g":"run","word":"Kayd","text":"Nuqul la keydiyay oo xogtaada hore ah, oo lagu noqon karo haddii wax lumaan ama waxyeeloobaan. AI-gile waxay maalin kasta samaysaa kayd sabuuradahaaga.","also":["kaydad","backup","nuqul kayd"]},{"id":"restore","g":"run","word":"Soo celin","text":"Xogta oo laga soo celiyo kayd. Kayd runtii wuxuu tirsadaa marka aad ogtahay in la soo celin karo, sidaa darteed waa mudan tahay in mar mar la tijaabiyo.","also":["soo celi","la soo celiyay","restore"]},{"id":"backlog","g":"team","word":"Backlog","text":"Fikrado iyo shaqo aan weli la qorshayn. Waxba halkaas looma shaqeeyo ilaa ay u dhaqaaqdo Waxa la sameeyo."},{"id":"sprint","g":"team","word":"Sprint","text":"Muddo gaaban oo shaqo ah (inta badan hal ama laba usbuuc) oo leh kaarar la isku raacay in la dhammeeyo.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"Hubin degdeg ah: waxa xubin kasta qabatay, waxa xiga ee ay samayn doonto, iyo waxa joojinaya.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Board leh tiirar (Waxa la sameeyo, Socda, La dhammeeyay) halkaas oo kaararku ka dhaqaaqaan bidix ilaa midig marka shaqadu socoto."},{"id":"wip","g":"team","word":"WIP limit","text":"Shaqo socota: kaararka ugu badan ee tiirku qaadi karo, si kooxdu u dhammeyso wax kahor intaysan bilaabin kuwo dheeraad ah.","also":["WIP"]},{"id":"dod","g":"team","word":"Qeexidda La dhammeeyay","text":"Liiska gaaban ee kooxda ee waxa “dhammaaday” macnaheedu yahay, sida la tijaabiyay oo la sharraxay, ka hor inta kaar laguu dhiibin. Mataanaheeda, Qeexidda Diyaar, waxay sheegtaa goorta kaar ku filan yahay in la bilaabo.","also":["Definition of Done","Qeexidda Diyaar","Definition of Ready"]},{"id":"testpile","g":"team","word":"Xirmada tijaabada","text":"Kaarrada la dhammeeyay ee sugaya inaad tijaabiso, mid mid. Mid aqbal ama dib ugu celi qoraal, kan xigaana wuu soo baxayaa.","also":["xirmooyinka tijaabada"]},{"id":"retro","g":"team","word":"Dib-eegis","text":"Dib u eegis sida ay kooxdu u shaqeyso, si loogu heshiiyo hal shay oo si fiican loo sameeyo. AI-gile, dib-eegis waxay soo jeedisaa isbeddel habka shaqada kooxda, adiguna waxaad dhahdaa Hore u soco ama Wali ma aha.","also":["retro","retrospective","dib-eegisyo"]},{"id":"peerreview","g":"team","word":"Peer review","text":"Indho labaad: AI kale ayaa hubisa shaqada kaar kasta ka hor inta uusan kuu soo gaarin, si khaladaad yar ay u dhaafaan.","also":["dib-u-eegis asxaab","code review"]},{"id":"swarm","g":"team","word":"Koox wada shaqeysa","text":"Gacan walba shaqada: koox kasta waxay dhigtaa shaqo kale si ay u caawiso hal mashruuc oo degdeg ah ilaa la xalliyo. Mashaariicda kale way sugaan inta lagu jiro.","also":["swarm","swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Qofka shaqada socodsiiya: arka kaarrada xayiran, dhiirrigeliya kooxaha oo ku xasuusiya waxa sugaya. AI-gile, Lead Scrum Master ayaa tan ka sameeya mashruuc kasta.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"AI naftiisa u shaqeeya hawl: wuxuu akhriyaa koodhka, wuxuu sameeyaa isbeddello, wuxuu socodsiiyaa hubin, wuuna soo sheegaa.","also":["agents"]},{"id":"token","g":"team","word":"Token","text":"Cutubka lagu tiriyo isticmaalka AI: qiyaas dhawr xaraf oo qoraal ah oo la akhriyay ama la qoray. Token yar, qorshahaaga wax badan ayaa hadha.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Amar yar oo naftiisa u socda waqti go'an, tusaale marka kalfadhi AI bilaabmo, si kooxdu u maqasho faallooyinkaaga.","also":["hooks"]}]}};
